changed="$(git diff --name-only "$merge_base"..HEAD)"

src_changed="$(printf '%s\n' "$changed" | grep -E '^src/' | grep -vE '\.test\.ts$' || true)"

if [ -z "$src_changed" ]; then
  echo "check-changelog: no shipped source changed since ${base}."
  exit 0
